[CmdletBinding()]
param(
    [Parameter(Mandatory = $true)][string]$ManifestPath,
    [Parameter(Mandatory = $true)][string]$ValidationReceiptPath,
    [Parameter(Mandatory = $true)][string]$OutputPath,
    [Parameter(Mandatory = $true)][string]$OutputMarkdownPath,
    [Parameter(Mandatory = $true)][string]$AuthorizationRequestPath,
    [Parameter(Mandatory = $true)][string]$FastReleasePromptPath
)
$ErrorActionPreference='Stop'
Set-StrictMode -Version Latest
Import-Module (Join-Path $PSScriptRoot 'pr90_probe_b_attempt22_contract_v1.psm1') -Force
if(-not(Test-Pr90ProbeBShaSidecar $ManifestPath "$ManifestPath.sha256")-or-not(Test-Pr90ProbeBShaSidecar $ValidationReceiptPath "$ValidationReceiptPath.sha256")){throw 'Attempt 22 manifest or validation sidecar mismatch.'}
$manifest=Get-Content -Raw -LiteralPath $ManifestPath|ConvertFrom-Json -Depth 100
$validation=Get-Content -Raw -LiteralPath $ValidationReceiptPath|ConvertFrom-Json -Depth 100
$manifestSha256=Get-Pr90ProbeBSha256 $ManifestPath
if([string]$manifest.canonical_payload_sha256-cne(Get-Pr90ProbeBCanonicalSha256 $manifest)-or-not(Test-Pr90Attempt22ValidationReceiptV4 -Validation $validation -Manifest $manifest -ExpectedManifestPath $ManifestPath -ExpectedManifestSha256 $manifestSha256)){throw 'Attempt 22 validation is not an exact canonical PASS.'}
$validatorPath=Join-Path $PSScriptRoot 'pr90_attempt22_authorization_validator_v4.ps1';$contractPath=Join-Path $PSScriptRoot 'pr90_probe_b_attempt22_contract_v1.psm1'
if((Get-Pr90ProbeBSha256 $PSCommandPath)-cne[string]$manifest.authorization_seal_builder_sha256-or(Get-Pr90ProbeBSha256 $validatorPath)-cne[string]$manifest.authorization_validator_sha256-or(Get-Pr90ProbeBSha256 $contractPath)-cne[string]$manifest.attempt22_contract_module_sha256){throw 'Attempt 22 seal executor identity mismatch.'}
if([IO.Path]::GetFullPath($OutputPath)-cne[IO.Path]::GetFullPath([string]$manifest.formal_authorization_seal_path)-or[IO.Path]::GetFullPath($ValidationReceiptPath)-cne[IO.Path]::GetFullPath([string]$manifest.formal_authorization_validation_receipt_path)){throw 'Attempt 22 planned authority output path mismatch.'}
foreach($futurePath in @($manifest.formal_authorization_consumption_receipt_path,$manifest.formal_prelaunch_ignored_inventory_path,$manifest.formal_evidence_root)){if(Test-Path -LiteralPath ([string]$futurePath)){throw "Attempt 22 future formal path already exists: $futurePath"}}
$plannedOutputs=@($OutputPath,"$OutputPath.sha256",$OutputMarkdownPath,$AuthorizationRequestPath,$FastReleasePromptPath)|ForEach-Object{[IO.Path]::GetFullPath([string]$_)}
if(@($plannedOutputs|Select-Object -Unique).Count-ne$plannedOutputs.Count){throw 'Attempt 22 authority output paths must be distinct.'}
foreach($plannedOutput in $plannedOutputs){if(Test-Path -LiteralPath $plannedOutput){throw "Attempt 22 authority output path already exists: $plannedOutput"}}
    $seal=[pscustomobject][ordered]@{schema='Pr90Attempt22AuthorizationSealV4';status='SEALED';created_at_utc=[DateTimeOffset]::UtcNow.ToString('o');authorization_id=[string]$manifest.authorization_id;authorized_run_id=[string]$manifest.authorized_run_id;formal_evidence_root=[IO.Path]::GetFullPath([string]$manifest.formal_evidence_root);authorization_seal_path=[IO.Path]::GetFullPath($OutputPath);authorization_consumption_receipt_path=[IO.Path]::GetFullPath([string]$manifest.formal_authorization_consumption_receipt_path);formal_prelaunch_ignored_inventory_path=[IO.Path]::GetFullPath([string]$manifest.formal_prelaunch_ignored_inventory_path);formal_terminal_manifest_path=[IO.Path]::GetFullPath([string]$manifest.formal_terminal_manifest_path);formal_finalizer_result_path=[IO.Path]::GetFullPath([string]$manifest.formal_finalizer_result_path);product_head_sha=[string]$manifest.product_head_sha;product_tree_sha=[string]$manifest.product_tree_sha;tooling_head_sha=[string]$manifest.tooling_head_sha;tooling_tree_sha=[string]$manifest.tooling_tree_sha;tooling_manifest_sha256=[string]$manifest.tooling_manifest_sha256;tooling_seal_sha256=[string]$manifest.tooling_seal_sha256;attempt22_contract_module_sha256=[string]$manifest.attempt22_contract_module_sha256;listener_parity_contract_version=[int]$manifest.listener_parity_contract_version;listener_core_normalizer_sha256=[string]$manifest.listener_core_normalizer_sha256;bracketed_cohort_controller_sha256=[string]$manifest.bracketed_cohort_controller_sha256;listener_forensics_sha256=[string]$manifest.listener_forensics_sha256;probe_b_v2_id=[string]$manifest.probe_b_v2_id;probe_b_v2_result_sha256=[string]$manifest.probe_b_result_sha256;probe_b_v2_attestation_sha256=[string]$manifest.probe_b_attestation_sha256;probe_b_v2_recovery_receipt_sha256=[string]$manifest.probe_b_recovery_receipt_sha256;probe_b_frozen_input_inventory_sha256=[string]$manifest.probe_b_frozen_input_inventory_sha256;probe_b_post_import_baseline_sha256=[string]$manifest.probe_b_post_import_baseline_sha256;probe_b_class_cache_sha256=[string]$manifest.probe_b_class_cache_sha256;probe_b_recovery_contract_module_sha256=[string]$manifest.probe_b_recovery_contract_module_sha256;probe_b_execution_tooling_head_sha=[string]$manifest.probe_b_execution_tooling_head_sha;probe_b_execution_tooling_tree_sha=[string]$manifest.probe_b_execution_tooling_tree_sha;probe_b_execution_tooling_seal_sha256=[string]$manifest.probe_b_execution_tooling_seal_sha256;probe_b_recovery_tooling_head_sha=[string]$manifest.probe_b_recovery_tooling_head_sha;probe_b_recovery_tooling_tree_sha=[string]$manifest.probe_b_recovery_tooling_tree_sha;probe_b_recovery_tooling_manifest_sha256=[string]$manifest.probe_b_recovery_tooling_manifest_sha256;probe_b_recovery_tooling_seal_sha256=[string]$manifest.probe_b_recovery_tooling_seal_sha256;runtime_reachable_tooling_hash_mismatch_count=[int]$manifest.runtime_reachable_tooling_hash_mismatch_count;sealed_baseline_sha256=[string]$manifest.sealed_baseline_sha256;class_cache_sha256=[string]$manifest.class_cache_sha256;godot_executable_sha256=[string]$manifest.godot_executable_sha256;godot_gui_sha256=[string]$manifest.godot_gui_sha256;godot_console_sha256=[string]$manifest.godot_console_sha256;import_finalizer_sha256=[string]$manifest.probe_b_finalizer_binding_sha256;import_runner_sha256=[string]$manifest.import_runner_sha256;manifest_path=[IO.Path]::GetFullPath($ManifestPath);manifest_sha256=$manifestSha256;validation_receipt_path=[IO.Path]::GetFullPath($ValidationReceiptPath);validation_receipt_sha256=Get-Pr90ProbeBSha256 $ValidationReceiptPath;authorized_run_count=1;automatic_retry_allowed=$false;formal_mcp_execution_count=0;authorized_run_count_consumed=0;canonical_payload_sha256=''}
$seal.canonical_payload_sha256=Get-Pr90ProbeBCanonicalSha256 $seal
$md="# PR #90 Attempt 22 Authorization Seal`n`n- Status: SEALED`n- Authorization: $($seal.authorization_id)`n- Run: $($seal.authorized_run_id)`n- Product: $($seal.product_head_sha) / $($seal.product_tree_sha)`n- Tooling: $($seal.tooling_head_sha) / $($seal.tooling_tree_sha)`n- Automatic retry: false`n- Formal MCP executed: 0"
$sealBytes=[Text.UTF8Encoding]::new($false).GetBytes(($seal|ConvertTo-Json -Depth 100));$predictedSealSha256=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($sealBytes)).ToLowerInvariant()
    $request="# PR #90 Attempt 22 Exact-SHA MCP Authorization Request`n`nAUTHORIZED_RUN_ID=$($manifest.authorized_run_id)`nPRODUCT_HEAD_SHA=$($manifest.product_head_sha)`nPRODUCT_TREE_SHA=$($manifest.product_tree_sha)`nTOOLING_HEAD_SHA=$($manifest.tooling_head_sha)`nTOOLING_TREE_SHA=$($manifest.tooling_tree_sha)`nTOOLING_MANIFEST_SHA256=$($manifest.tooling_manifest_sha256)`nTOOLING_SEAL_SHA256=$($manifest.tooling_seal_sha256)`nPROBE_B_EXECUTION_TOOLING_HEAD_SHA=$($manifest.probe_b_execution_tooling_head_sha)`nPROBE_B_EXECUTION_TOOLING_TREE_SHA=$($manifest.probe_b_execution_tooling_tree_sha)`nPROBE_B_EXECUTION_TOOLING_SEAL_SHA256=$($manifest.probe_b_execution_tooling_seal_sha256)`nPROBE_B_RECOVERY_RECEIPT_SHA256=$($manifest.probe_b_recovery_receipt_sha256)`nPROBE_B_POST_IMPORT_BASELINE_SHA256=$($manifest.probe_b_post_import_baseline_sha256)`nPROBE_B_CLASS_CACHE_SHA256=$($manifest.probe_b_class_cache_sha256)`nNEW_TOOLING_HEAD_SHA=$($manifest.tooling_head_sha)`nNEW_TOOLING_TREE_SHA=$($manifest.tooling_tree_sha)`nNEW_TOOLING_MANIFEST_SHA256=$($manifest.tooling_manifest_sha256)`nNEW_TOOLING_SEAL_SHA256=$($manifest.tooling_seal_sha256)`nLISTENER_PARITY_CONTRACT_VERSION=$($manifest.listener_parity_contract_version)`nLISTENER_CORE_NORMALIZER_SHA256=$($manifest.listener_core_normalizer_sha256)`nBRACKETED_COHORT_CONTROLLER_SHA256=$($manifest.bracketed_cohort_controller_sha256)`nLISTENER_FORENSICS_SHA256=$($manifest.listener_forensics_sha256)`nPROBE004_RESULT_SHA256=$($manifest.probe004_result_sha256)`nPROBE004_ATTESTATION_SHA256=$($manifest.probe004_attestation_sha256)`nPROBE_B_V2_ID=$($manifest.probe_b_v2_id)`nPROBE_B_V2_RESULT_SHA256=$($manifest.probe_b_result_sha256)`nPROBE_B_V2_ATTESTATION_SHA256=$($manifest.probe_b_attestation_sha256)`nPREFORMAL_DRY_RUN_SHA256=$($manifest.preformal_dry_run_sha256)`nFORMAL_GATE_1_79_RECEIPT_SHA256=$($manifest.formal_gate_1_79_receipt_sha256)`nSEALED_BASELINE_SHA256=$($manifest.sealed_baseline_sha256)`nCLASS_CACHE_SHA256=$($manifest.class_cache_sha256)`nIMPORT_PASS1_MANIFEST_SHA256=$($manifest.import_pass1_manifest_sha256)`nIMPORT_PASS2_MANIFEST_SHA256=$($manifest.import_pass2_manifest_sha256)`nIMPORT_FINALIZER_DRY_RUN_SHA256=$($manifest.import_finalizer_dry_run_evidence_sha256)`nGODOT_EXECUTABLE_SHA256=$($manifest.godot_executable_sha256)`nATTEMPT22_AUTHORIZATION_MANIFEST_SHA256=$(Get-Pr90ProbeBSha256 $ManifestPath)`nATTEMPT22_AUTHORIZATION_SEAL_SHA256=$predictedSealSha256`n`nAUTHORIZED_NEW_EXACT_SHA_MCP_RUN_COUNT=1`nAUTHORIZED_EXACT_SHA_MCP_COUNT=1`nAUTOMATIC_RETRY_ALLOWED=false`nFORMAL_MCP_EXECUTION_COUNT=0`nAUTHORIZED_RUN_COUNT_CONSUMED=0"
$request=$request.Replace("`nGODOT_EXECUTABLE_SHA256=$($manifest.godot_executable_sha256)`n","`nGODOT_GUI_SHA256=$($manifest.godot_gui_sha256)`nGODOT_CONSOLE_SHA256=$($manifest.godot_console_sha256)`nGODOT_EXECUTABLE_SHA256_LEGACY_CONSOLE_ALIAS=$($manifest.godot_executable_sha256)`n")
Write-Pr90ProbeBImmutableText -Path $OutputMarkdownPath -Text $md|Out-Null
Write-Pr90ProbeBImmutableText -Path $AuthorizationRequestPath -Text $request|Out-Null
  $fast="# Post-Attempt22 Release Chain`n`nMASTER_TASK_ID=SPACE_SYNDICATE_CONTINUOUS_V076_DELIVERY_CHECKPOINT_002 authorizes execution after the sealed Exact-SHA MCP prerequisite passes: Viewport; 64 Seed Presentation Parity; Headless Matrix; Product 2,000; PR #90 merge; v0.7.5 tag. Each stage remains fail-closed and preserves prior evidence.`n`nCURRENT_TASK_EXECUTION_COUNT_FOR_ALL_LISTED_STAGES=0"
Write-Pr90ProbeBImmutableText -Path $FastReleasePromptPath -Text $fast|Out-Null
Write-Pr90ProbeBImmutableJson -Path $OutputPath -Value $seal -WriteSha256Sidecar|Out-Null
if((Get-Pr90ProbeBSha256 $OutputPath)-cne$predictedSealSha256){throw 'Attempt 22 authorization Seal byte prediction mismatch.'}
$seal|ConvertTo-Json -Depth 100 -Compress
